fn iabs(v: i32) -> i32 {
    if v < 0 { -v } else { v }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let ax: i32 = w / 2;
    let ay: i32 = 60;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 6 {
            host::display::state_set(8 + i * 2, ax);
            host::display::state_set(9 + i * 2, ay + i * 30);
            i = i + 1;
        }
    }
    let mut nx = [0; 6];
    let mut ny = [0; 6];
    let mut i: i32 = 0;
    while i < 6 {
        nx[i] = host::display::state_get(8 + i * 2);
        ny[i] = host::display::state_get(9 + i * 2);
        i = i + 1;
    }
    i = 1;
    while i < 6 {
        ny[i] = ny[i] + 3;
        i = i + 1;
    }
    let down: i32 = host::display::pointer_down();
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut grab: i32 = host::display::state_get(1);
    if down == 1 {
        if grab == 0 && iabs(px - nx[5]) < 26 && iabs(py - ny[5]) < 26 {
            grab = 1;
        }
        if grab == 1 {
            nx[5] = px;
            ny[5] = py;
        }
    } else {
        grab = 0;
    }
    host::display::state_set(1, grab);
    let mut pass: i32 = 0;
    while pass < 3 {
        nx[0] = ax;
        ny[0] = ay;
        i = 1;
        while i < 6 {
            let dx: i32 = nx[i] - nx[i - 1];
            let dy: i32 = ny[i] - ny[i - 1];
            let len: i32 = iabs(dx) + iabs(dy);
            if len > 0 {
                let ex: i32 = dx * (len - 30) / len;
                let ey: i32 = dy * (len - 30) / len;
                if i == 1 {
                    nx[i] = nx[i] - ex;
                    ny[i] = ny[i] - ey;
                } else {
                    nx[i] = nx[i] - ex / 2;
                    ny[i] = ny[i] - ey / 2;
                    nx[i - 1] = nx[i - 1] + ex / 2;
                    ny[i - 1] = ny[i - 1] + ey / 2;
                }
            }
            i = i + 1;
        }
        pass = pass + 1;
    }
    i = 0;
    while i < 6 {
        host::display::state_set(8 + i * 2, nx[i]);
        host::display::state_set(9 + i * 2, ny[i]);
        i = i + 1;
    }
    host::display::clear(0x101014);
    host::display::fill_rect(ax - 20, ay - 12, 40, 12, 0x505860);
    i = 1;
    while i < 6 {
        host::display::draw_line(nx[i - 1], ny[i - 1], nx[i], ny[i], 0x909090);
        i = i + 1;
    }
    i = 0;
    while i < 6 {
        let c: i32 = if i == 5 { 0xffb030 } else { 0xd0d0d0 };
        host::display::fill_rect(nx[i] - 4, ny[i] - 4, 8, 8, c);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "DRAG THE TAIL", 0x606060, 1);
    host::display::present();
}
